       current_deposit_amount, streak_count, created_at, updated_at
FROM group_users
WHERE group_id = #{groupId}
  AND user_id = #{userId}

SELECT group_user_id, group_id, user_id, group_user_status, approved_at,
       current_deposit_amount, streak_count, created_at, updated_at
FROM group_users
WHERE group_id = #{groupId}
  AND user_id = #{userId}
FOR UPDATE

SELECT account_id, user_id, account_type, account_number, bank_name,
       balance, created_at, account_status, account_name, updated_at
FROM accounts
WHERE account_id = #{accountId}
  AND user_id = #{userId}
FOR UPDATE

mapper.update:
UPDATE accounts
SET balance = balance - #{amount}
WHERE account_id = #{accountId}
  AND user_id = #{userId}
  AND balance >= #{amount}

UPDATE moim_accounts
SET balance = balance + #{amount}
WHERE moim_account_id = #{moimAccountId}

UPDATE group_users
SET current_deposit_amount = current_deposit_amount + #{amount}
WHERE group_user_id = #{groupUserId}

UPDATE group_users
SET group_user_status = #{status}
WHERE group_user_id = #{groupUserId}

